function foliage(i){return `<g opacity=".72">${palm(20,95,.62)}${palm(182,62,.5,-1)}</g><path d="M17 161Q42 146 68 163T119 159T191 165v30H17Z" fill="${palettes[i][2]}" opacity=".8"/>`;}
function scene(i){if(i>=6)return `<svg x="42" y="122" width="276" height="343" viewBox="0 0 200 240" preserveAspectRatio="xMidYMid slice">${newScenes[ids[i]]}<path d="M0 0h200v240H0Z" fill="url(#grain)" opacity=".16"/></svg>`;const p=palettes[i];return `<svg x="42" y="122" width="276" height="343" viewBox="0 0 200 240" preserveAspectRatio="xMidYMid slice"><path d="M0 0h200v240H0Z" fill="${p[0]}"/><path d="M0 17Q70-4 128 31T200 17v47Q155 94 96 56T0 61Z" fill="#f4d49e" opacity=".7"/><circle cx="${i%2?70:131}" cy="59" r="35" fill="#efd4a1"/><g stroke="#805c3f" opacity=".35">${Array.from({length:12},(_,k)=>{const a=k*Math.PI/6;return `<path d="M${131+Math.cos(a)*39} ${59+Math.sin(a)*39}l${Math.cos(a)*12} ${Math.sin(a)*12}"/>`;}).join('')}</g>${foliage(i)}${i===2||i===3?`<g transform="translate(0 2)" opacity=".9">${houses()}</g>`:''}<path d="M0 210l82-44 118 37v37H0Z" fill="${p[1]}"/><path d="M0 220l100-44 100 39" stroke="#f2cc86" stroke-width="2" opacity=".6"/><g transform="translate(0 ${i===4?52:50})">${subjects[i]}</g><g fill="#efe1b6" opacity=".8">${star(29,79,5)}${star(162,108,5)}</g><path d="M0 0h200v240H0Z" fill="url(#grain)" opacity=".26"/></svg>`;}
function tile(x,y){return `<g transform="translate(${x},${y})" fill="none" stroke="#c49d56" stroke-width="1.5"><path d="M0-12Q15-18 12 0Q18 15 0 12Q-15 18-12 0Q-18-15 0-12Z"/><path d="m0-7 7 7-7 7-7-7Z"/><circle r="2" fill="#c49d56"/></g>`;}
export function cardSVG(card,back=false){const i=ids.indexOf(card.id);if(i<0)throw new Error('No artwork for card: '+card.id);return `<svg xmlns="http://www.w3.org/2000/svg" width="360" height="600" viewBox="0 0 360 600" role="img" aria-label="${back?'Little Red Deck ornamental card back':card.name+' — '+meanings[i]}"><defs><pattern id="grain" width="32" height="32" patternUnits="userSpaceOnUse"><path d="m2 4 5-1m13 5 8-2M6 17l8-2m11 8 5-1M2 28l9-2" stroke="#725532" stroke-width=".7" fill="none"/></pattern><clipPath id="arch"><path d="M42 465V232a138 110 0 0 1 276 0v233Z"/></clipPath></defs><rect x="1" y="1" width="358" height="598" rx="15" fill="#182f31" stroke="#d3b376" stroke-width="2"/><rect x="14" y="14" width="332" height="572" rx="8" fill="none" stroke="#bd995b"/><path d="M25 85V28h60m190 0h60v57M25 515v57h60m190 0h60v-57" fill="none" stroke="#d5b975" stroke-width="2"/>${[tile(35,38),tile(325,38),tile(35,562),tile(325,562)].join('')}${back?`<rect x="44" y="85" width="272" height="429" rx="135" fill="#244743" stroke="#b89353"/><g opacity=".6">${Array.from({length:7},(_,r)=>Array.from({length:4},(_,c)=>tile(75+c*70,125+r*58)).join('')).join('')}</g><path d="m180 183 80 115-80 115-80-115Z" fill="#a44934" stroke="#d4b16d" stroke-width="3"/><circle cx="180" cy="298" r="54" fill="#182f31" stroke="#d4b16d"/><g transform="translate(180 298)" fill="#d4b16d">${Array.from({length:8},(_,k)=>`<path transform="rotate(${k*45})" d="M0 0Q-29-42 0-42Q29-42 0 0"/>`).join('')}<circle r="10" fill="#a44934"/></g><text x="180" y="64" text-anchor="middle" fill="#ecd5a2" font-family="Georgia,serif" font-size="17" letter-spacing="3">LITTLE RED DECK</text><text x="180" y="546" text-anchor="middle" fill="#ecd5a2" font-family="Georgia,serif" font-size="13" letter-spacing="3">THE EVERYDAY ARCANA</text>`:`<circle cx="180" cy="58" r="24" fill="#a44934" stroke="#d3b376"/><text x="180" y="65" text-anchor="middle" fill="#f5e1b6" font-family="Georgia,serif" font-size="23">${roman[i]}</text><g fill="#d3b376">${star(114,58,6)}${star(246,58,6)}</g><text x="180" y="106" text-anchor="middle" fill="#e9d2a1" font-family="Georgia,serif" font-size="16" letter-spacing="2">${meanings[i]}</text><g clip-path="url(#arch)">${scene(i)}</g><path d="M42 465V232a138 110 0 0 1 276 0v233Z" fill="none" stroke="#d3b376" stroke-width="3"/><path d="M36 465V232a144 116 0 0 1 288 0v233" fill="none" stroke="#d3b376" stroke-width=".7"/><path d="M45 480h270" stroke="#b99553"/><text x="180" y="511" text-anchor="middle" fill="#f3debc" font-family="Georgia,serif" font-size="${card.name.length>19?20:24}">${card.name}</text><text x="180" y="539" text-anchor="middle" fill="#d3b376" font-family="Georgia,serif" font-size="12" letter-spacing="3">${card.word.toUpperCase()}</text><text x="180" y="570" text-anchor="middle" fill="#a8b4a4" font-family="Georgia,serif" font-size="9" letter-spacing="3">SINGAPORE · ${card.theme.toUpperCase()}</text>`}</svg>`;}
